document.addEventListener("DOMContentLoaded",()=>{const address="ws://"+window.location.host+"/ws/listener/";let interval=null;let connectionError=0;function init(){if(connectionError>=6){clearInterval(interval);console.log("Connection Error: Aborted");return}let chatSocket=new WebSocket(address);chatSocket.onclose=function(){document.body.classList.add("offline");interval=setInterval(init,1e4);connectionError++};chatSocket.onerror=function(){document.body.classList.add("offline");chatSocket.close()};chatSocket.onopen=function(){document.body.classList.remove("offline");if(interval){clearInterval(interval);interval=null}};chatSocket.onmessage=function(e){const payload=JSON.parse(e.data);console.log(payload)};console.log(`Channel initialised at ${address}`)}init()});
